	table["<<"] = 10;
	table[";"] = 11;
	table[","] = 12;
	table["="] = 13;
	table["*"] = 14;
	table["/"] = 15;
	return table;
}
//判断单词类型
int wtMatch(const string word) {
	static const map<string, int> wordType = buildWordTypeTable();
	//先查关键字与界符运算符表
	map<string, int>::const_iterator it = wordType.find(word);
	if (it != wordType.end()) {
		return it->second;
	}
	//再判断标识符与十进制整数
	if (IsIdentifier(word)) {
		return 16;
	}
	if (IsNum(word)) {
		return 17;
	}
	//都不满足则是非法单词
	return 0;
}
